import { useState, type ChangeEvent } from 'react';
import { Button, Card, Input, Stack, Stepper, Text } from '@jinx-ui/react';

type FormValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: FormValues) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_VALUES: FormValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_ROWS: Array<[string, keyof FormValues]> = [
  ['Имя', 'name'],
  ['E-mail', 'email'],
  ['Телефон', 'phone'],
  ['Город', 'city'],
  ['Улица, дом', 'street'],
  ['Индекс', 'zip'],
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<FormValues>(EMPTY_VALUES);

  const isLast = step === STEPS.length - 1;

  const bind = (field: keyof FormValues) => ({
    value: values[field],
    onChange: (event: ChangeEvent<HTMLInputElement>) =>
      setValues((prev) => ({ ...prev, [field]: event.target.value })),
  });

  return (
    <Card className="jx-card">
      <Stack direction="vertical" gap="var(--jx-space-lg)">
        <Stepper activeStep={step} steps={STEPS.map((label) => ({ label }))} />

        {step === 0 && (
          <Stack direction="vertical" gap="var(--jx-space-md)">
            <Input label="Имя" name="name" autoComplete="name" {...bind('name')} />
            <Input label="E-mail" name="email" type="email" autoComplete="email" {...bind('email')} />
            <Input label="Телефон" name="phone" type="tel" autoComplete="tel" {...bind('phone')} />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="vertical" gap="var(--jx-space-md)">
            <Input label="Город" name="city" autoComplete="address-level2" {...bind('city')} />
            <Input label="Улица, дом" name="street" autoComplete="street-address" {...bind('street')} />
            <Input label="Индекс" name="zip" autoComplete="postal-code" {...bind('zip')} />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="vertical" gap="var(--jx-space-sm)">
            {REVIEW_ROWS.map(([label, field]) => (
              <Stack key={field} direction="horizontal" justify="space-between" gap="var(--jx-space-md)">
                <Text tone="muted">{label}</Text>
                <Text>{values[field] || '—'}</Text>
              </Stack>
            ))}
          </Stack>
        )}

        <Stack direction="horizontal" justify="space-between" gap="var(--jx-space-md)">
          <Button variant="secondary" disabled={step === 0} onClick={() => setStep((s) => s - 1)}>
            Назад
          </Button>
          {isLast ? (
            <Button variant="primary" onClick={() => onSubmit(values)}>
              Отправить
            </Button>
          ) : (
            <Button variant="primary" onClick={() => setStep((s) => s + 1)}>
              Дальше
            </Button>
          )}
        </Stack>
      </Stack>
    </Card>
  );
}

